L34_1 = "\194\183 \236\158\165\235\185\132, \235\160\136\235\178\168\236\151\133, \234\176\149\237\153\148\235\161\156 \236\150\187\235\138\148 \235\138\165\235\160\165\236\185\152\235\138\148 \236\157\188\235\182\128\235\167\140 \236\160\129\236\154\169\235\144\169\235\139\136\235\139\164.\n\194\183 \236\158\144\236\139\160\234\179\188 \235\185\132\236\138\183\237\149\156 \236\138\185\236\160\144\236\157\152 \236\156\160\236\160\128\236\153\128 \235\167\164\236\185\173\235\144\169\235\139\136\235\139\164.\n\194\183 \235\167\164\236\185\173 \234\184\176\236\164\128 \236\138\185\236\160\144\236\151\144 \236\158\145\236\160\132 \235\138\165\235\160\165\236\157\180 \235\176\152\236\152\129\235\144\169\235\139\136\235\139\164. \236\158\145\236\160\132 \235\138\165\235\160\165\236\157\180 \235\134\146\235\139\164\235\169\180 \236\158\144\236\139\160\235\179\180\235\139\164 \235\134\146\236\157\128 \236\138\185\236\160\144\236\157\152 \236\156\160\236\160\128\236\153\128 \235\167\164\236\185\173\235\144\160 \236\136\152 \236\158\136\236\156\188\235\169\176, \236\158\145\236\160\132 \235\138\165\235\160\165\236\157\180 \235\130\174\235\139\164\235\169\180 \236\158\144\236\139\160\235\179\180\235\139\164 \235\130\174\236\157\128 \236\138\185\236\160\144\236\157\152 \236\156\160\236\160\128\236\153\128 \235\167\164\236\185\173\235\144\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.\n\194\183 \236\158\144\236\139\160\235\179\180\235\139\164 \235\134\146\236\157\128 \236\138\185\236\160\144\236\157\152 \236\156\160\236\160\128\236\151\144\234\178\140 \236\138\185\235\166\172\237\149\152\235\169\180 \236\138\185\236\160\144\236\157\132 \235\167\142\236\157\180 \236\150\187\234\179\160, \236\167\136 \234\178\189\236\154\176 \236\160\129\234\178\140 \236\158\131\236\138\181\235\139\136\235\139\164.\n\194\183 \236\158\144\236\139\160\235\179\180\235\139\164 \235\130\174\236\157\128 \236\138\185\236\160\144\236\157\152 \236\156\160\236\160\128\236\151\144\234\178\140 \236\138\185\235\166\172\237\149\152\235\169\180 \236\138\185\236\160\144\236\157\132 \236\160\129\234\178\140 \236\150\187\234\179\160, \236\167\136 \234\178\189\236\154\176 \235\167\142\236\157\180 \236\158\131\236\138\181\235\139\136\235\139\164.\n\194\183 \236\158\144\236\139\160\236\157\180 \236\131\129\235\140\128\235\179\180\235\139\164 \236\138\185\236\160\144\236\157\180 \237\152\132\236\160\128\237\158\136 \235\134\146\236\167\128\235\167\140, \236\158\145\236\160\132 \235\138\165\235\160\165\236\157\180 \237\152\132\236\160\128\237\158\136 \235\130\174\236\157\128 \234\178\189\236\154\176, \236\138\185\236\160\144 \234\179\132\236\130\176\236\139\157\236\157\180 \235\179\180\236\160\149\235\144\169\235\139\136\235\139\164. \236\157\180 \234\178\189\236\154\176, \234\184\176\236\161\180\235\179\180\235\139\164 \236\131\129\235\140\128\235\161\156\235\182\128\237\132\176 \236\150\187\235\138\148 \236\138\185\236\160\144\236\157\132 \234\184\176\235\140\128\237\149\160 \236\136\152 \236\158\136\236\156\188\235\169\176, \236\167\128\235\141\148\235\157\188\235\143\132 \236\138\185\236\160\144\236\157\132 \235\141\156 \236\158\131\236\138\181\235\139\136\235\139\164.\n\194\183 \236\138\185\236\160\144\236\157\132 \236\157\188\236\160\149 \236\157\180\236\131\129 \236\150\187\236\156\188\235\169\180 \236\131\129\236\156\132 \235\166\172\234\183\184\235\161\156 \236\152\172\235\157\188\234\176\136 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.\n\194\183 \236\157\188\235\182\128 \235\166\172\234\183\184\236\151\144\236\132\156, \237\149\180\235\139\185 \235\166\172\234\183\184\236\157\152 \236\138\185\236\160\144\235\179\180\235\139\164 100\236\160\144 \236\157\180\237\149\152\235\161\156 \235\150\168\236\150\180\236\167\128\235\169\180 \234\176\149\235\147\177\235\144\160 \236\136\152 \236\158\136\236\138\181\235\139\136\235\139\164.\n\194\183 \236\131\129\236\156\132 \235\166\172\234\183\184\236\151\144\236\132\156\235\138\148 \236\161\176\